const NODE_OPS = new Set(['X', 'A', 'B', 'C', 'K']);
const TRACK_OPS = new Set(['P', 'Q']);

// --- 圖片載入與快取 ---

function loadSkinImages() {
    const map = {};
    if (typeof Image === 'undefined') return map;
    for (const [key, dataUrl] of Object.entries(SKIN_DATA_URLS)) {
        const img = new Image();
        img.src = dataUrl;
        map[key] = img;
    }
    return map;
}

function isImgReady(img) {
    return Boolean(img && img.complete && img.naturalWidth > 0);
}

// --- Slide Code 語法擷取與驗證 ---

function extractSlideCodeCore(rawInput) {
    if (typeof rawInput !== 'string') return null;
    const trimmed = rawInput.trim();
    if (!trimmed) return null;

    const cleaned = trimmed.replace(/\[[^\]]*\]/g, '');
    const match = cleaned.match(/^(\*?)([1-8])([bxmhqf@?!$]*)(.*)$/);
    if (match) {
        const isSameHead = match[1] === '*';
        const startDigit = match[2];
        const headMods = match[3] || '';
        let rest = match[4] || '';
        rest = rest.replace(/[bxm]+$/, '');
        if (/^[ABCKPQ0-9]+$/.test(rest) && /[ABCKPQ]/.test(rest)) {
            return {
                core: `${startDigit}${rest}`,
                startPrefix: startDigit,
                modifiers: headMods,
                isSameHead
            };
        }
    }

    const direct = cleaned.replace(/^\*/, '');
    if (/^[0-9ABCKPQ]+$/.test(direct) && /[ABCKPQ]/.test(direct)) {
        return {
            core: direct,
            startPrefix: direct[0] || '',
            modifiers: '',
            isSameHead: cleaned.startsWith('*')
        };
    }

    return null;
}

function findSlideCodeNearCursor(text, start, end) {
    if (!text) return null;
    if (end > start) {
        const selected = text.slice(start, end);
        if (extractSlideCodeCore(selected)) return selected.trim();
    }

    const pos = Math.max(0, Math.min(text.length, start));
    let left = pos;
    let right = pos;
    const isTokenChar = (ch) => /[0-9A-Za-z*[\]:.#@?!$]/.test(ch);
    while (left > 0 && isTokenChar(text[left - 1])) left -= 1;
    while (right < text.length && isTokenChar(text[right])) right += 1;
    const token = text.slice(left, right);
    if (!token) return null;

    const parts = token.split('/');
    for (const part of parts) {
        const subParts = part.split(/(?=\*)/);
        for (const sub of subParts) {
            if (extractSlideCodeCore(sub)) return sub;
        }
    }
    return null;
}

function getNodeTrackRelation(nodeToken, trackId) {
    const op = nodeToken.op === 'X' || nodeToken.op === 'K' ? 'A' : nodeToken.op;
    const param = nodeToken.param;

    if (trackId === 0) return op === 'C' ? 'inside' : 'outside';
    if (trackId === 9) return op === 'A' ? 'on' : 'inside';

    if (op === 'C') return 'on';
    if (op === 'B') {
        const prevB = trackId === 1 ? 8 : trackId - 1;
        if (param === trackId || param === prevB) return 'inside';
    }
    return 'outside';
}

function formatToken(tok) {
    if (tok.op === 'X') return `(X)${tok.param}`;
    if (tok.op === 'C') return 'C';
    return `${tok.op}${tok.param}`;
}

function nodeLabel(tok) {
    if (tok.op === 'X') return `起點 A${tok.param}`;
    if (tok.op === 'K') return `終點 A${tok.param}`;
    if (tok.op === 'C') return '中心 C';
    return `${tok.op}${tok.param}`;
}

function trackName(id) {
    if (id === 0) return '中央圓';
    if (id === 9) return '最外圓';
    return `側邊圓 D${id}`;
}

function dirName(op) {
    return op === 'P' ? '逆時針' : '順時針';
}

function parseAndValidateSlideCode(rawInput) {
    const extracted = extractSlideCodeCore(rawInput);
    if (!extracted) {
        return {
            ok: false,
            empty: !rawInput || !rawInput.trim(),
            core: '',
            tokens: [],
            errors: rawInput && rawInput.trim()
                ? ['輸入內容不是有效的 Slide Code（僅允許 A, B, C, K, P, Q 與數字 0~9，或標準 Simai 修飾外殼）。']
                : [],
            segments: [],
            geometry: { primitives: [], nodes: [], tracksUsed: new Set() },
            judgmentQueue: []
        };
    }

    const code = extracted.core;
    const tokens = [];
    const errors = [];
    let lastOp = null;

    if (!/^[1-8]/.test(code)) {
        errors.push('Slide Code 必須以 1~8 數字（起點 A 區鍵位）開頭。');
    }

    let i = 0;
    while (i < code.length) {
        const ch = code[i];
        if (/[ABCKPQ]/.test(ch)) {
            if (ch === 'C') {
                tokens.push({ op: 'C', param: null, index: i, raw: 'C' });
                lastOp = 'C';
                i += 1;
                if (i < code.length && /[0-9]/.test(code[i])) {
                    errors.push(`位置 ${i + 1}：C 指令不可接任何數字參數（發現 "${code[i]}"）。`);
                    i += 1;
                }
                continue;
            }

            const next = code[i + 1];
            if (!next || !/[0-9]/.test(next)) {
                errors.push(`位置 ${i + 1}：指令 "${ch}" 後方缺少 0~9 數字參數。`);
                i += 1;
                continue;
            }
            const param = Number(next);
            tokens.push({ op: ch, param, index: i, raw: `${ch}${next}` });
            lastOp = ch;
            i += 2;
        } else if (/[0-9]/.test(ch)) {
            const param = Number(ch);
            if (tokens.length === 0) {
                tokens.push({ op: 'X', param, index: i, raw: ch });
                lastOp = 'X';
            } else if (!lastOp || lastOp === 'C') {
                errors.push(`位置 ${i + 1}：參數 "${ch}" 無法繼承前一個指令。`);
            } else {
                tokens.push({ op: lastOp, param, index: i, raw: ch, shorthand: true });
            }
            i += 1;
        } else {
            errors.push(`位置 ${i + 1}：不支援的字元 "${ch}"。`);
            i += 1;
        }
    }

    for (let idx = 0; idx < tokens.length; idx++) {
        const tok = tokens[idx];
        if ((tok.op === 'X' || tok.op === 'A' || tok.op === 'B' || tok.op === 'K') && (tok.param < 1 || tok.param > 8)) {
            errors.push(`指令 ${formatToken(tok)} 的參數必須為 1~8。`);
        }
        if (tok.op === 'K' && idx !== tokens.length - 1) {
            errors.push(`結束指令 ${formatToken(tok)} 只能出現在整條 Slide Code 的最後。`);
        }
    }

    if (tokens.length > 0 && tokens[tokens.length - 1].op !== 'K') {
        errors.push(`Slide Code 必須以 K1~K8 結尾（目前結尾為 ${formatToken(tokens[tokens.length - 1])}）。`);
    }

    const segments = [];
    for (let idx = 0; idx < tokens.length - 1; idx++) {
        const a = tokens[idx];
        const b = tokens[idx + 1];
        const aIsNode = NODE_OPS.has(a.op);
        const bIsNode = NODE_OPS.has(b.op);
        const aIsTrack = TRACK_OPS.has(a.op);
        const bIsTrack = TRACK_OPS.has(b.op);

        let kind = 'invalid';
        let desc = '';
        let segmentError = null;

        if (aIsNode && bIsNode) {
            kind = 'node-node';
            desc = `直線從 ${nodeLabel(a)} 前往 ${nodeLabel(b)}`;
        } else if (aIsNode && bIsTrack) {
            const rel = getNodeTrackRelation(a, b.param);
            if (rel === 'inside') {
                segmentError = `${formatToken(a)} 位於軌道 ${b.param}（${trackName(b.param)}）內部，禁止切入。`;
            } else if (rel === 'on') {
                kind = 'node-track-on';
                desc = `${nodeLabel(a)} 已位於軌道 ${b.param}（${trackName(b.param)}）圓周上，直接準備${dirName(b.op)}繞行`;
            } else {
                kind = 'node-track-tangent';
                desc = `從 ${nodeLabel(a)} 沿切線切入軌道 ${b.param}（${trackName(b.param)}），準備${dirName(b.op)}繞行`;
            }
        } else if (aIsTrack && bIsNode) {
            const rel = getNodeTrackRelation(b, a.param);
            if (rel === 'inside') {
                segmentError = `${nodeLabel(b)} 位於軌道 ${a.param}（${trackName(a.param)}）內部，無法沿切線離開。`;
            } else if (rel === 'on') {
                kind = 'track-node-on';
                desc = `沿軌道 ${a.param}（${trackName(a.param)}）${dirName(a.op)}繞行至 ${nodeLabel(b)} 圓周位置`;
            } else {
                kind = 'track-node-tangent';
                desc = `沿軌道 ${a.param}（${trackName(a.param)}）${dirName(a.op)}繞行至切點後，沿切線前往 ${nodeLabel(b)}`;
            }
        } else if (aIsTrack && bIsTrack) {
            if (a.op !== b.op) {
                segmentError = `${formatToken(a)} 與 ${formatToken(b)} 旋轉方向不同（P/Q 不可直接相接，需插入節點中轉）。`;
            } else if (a.param === b.param) {
                kind = 'track-lap';
                desc = `在軌道 ${a.param}（${trackName(a.param)}）上額外${dirName(a.op)}多繞一圈（360°）`;
            } else if ((a.param === 0 && b.param === 9) || (a.param === 9 && b.param === 0)) {
                segmentError = `禁止中央圓（0）與最外圓（9）直接互相轉移（${formatToken(a)} → ${formatToken(b)}）。`;
            } else if (a.param === 9 || b.param === 9) {
                kind = 'track-cotangent';
                desc = `透過側邊圓與最外圓的共切圓，從軌道 ${a.param} ${dirName(a.op)}平滑轉移至軌道 ${b.param}`;
            } else {
                kind = 'track-outer-tangent';
                desc = `沿外公切線從軌道 ${a.param}（${trackName(a.param)}）${dirName(a.op)}轉移至軌道 ${b.param}（${trackName(b.param)}）`;
            }
        }

        if (segmentError) errors.push(segmentError);
        segments.push({ from: a, to: b, kind, desc: segmentError || desc, valid: !segmentError });
    }

    const geometry = errors.length === 0 && tokens.length >= 2
        ? buildSlideGeometry(tokens)
        : { primitives: [], nodes: [], tracksUsed: new Set() };

    const judgmentQueue = errors.length === 0 && tokens.length >= 2
        ? estimateJudgmentQueue(tokens, geometry.primitives)
        : [];

    return {
        ok: errors.length === 0 && tokens.length >= 2,
        empty: false,
        core: code,
        tokens,
        errors,
        segments,
        geometry,
        judgmentQueue
    };
}

// --- 幾何計算與弧長參數化路徑 ---

const B_RADIUS_RATIO = Math.SQRT2 - 1;
const CENTRAL_TRACK_RATIO = 0.36;
const SIDE_TRACK_RATIO = 0.425;

function buttonAngle(k) {
    return (k - 2.5) * (Math.PI / 4);
}

function dZoneAngle(d) {
    return (d - 3) * (Math.PI / 4);
}

function getNodePos(tok) {
    if (tok.op === 'C') return { x: 0, y: 0 };
    const angle = buttonAngle(tok.param);
    const r = tok.op === 'B' ? B_RADIUS_RATIO : 1;
    return { x: Math.cos(angle) * r, y: Math.sin(angle) * r };
}

function getTrackCircle(id) {
    if (id === 0) return { id: 0, cx: 0, cy: 0, r: CENTRAL_TRACK_RATIO };
    if (id === 9) return { id: 9, cx: 0, cy: 0, r: 1 };
    const a = dZoneAngle(id);
    return {
        id,
        cx: Math.cos(a) * SIDE_TRACK_RATIO,
        cy: Math.sin(a) * SIDE_TRACK_RATIO,
        r: SIDE_TRACK_RATIO
    };
}

function normAngle(a) {
    let res = a % (Math.PI * 2);
    if (res < 0) res += Math.PI * 2;
    return res;
}

function getPointCircleTangent(pt, circle, ccw, isEntering) {
    const dx = pt.x - circle.cx;
    const dy = pt.y - circle.cy;
    const dist = Math.hypot(dx, dy);
    if (dist <= circle.r + 1e-6) {
        const ang = Math.atan2(dy, dx);
        return {
            x: circle.cx + Math.cos(ang) * circle.r,
            y: circle.cy + Math.sin(ang) * circle.r,
            angle: ang
        };
    }

    const base = Math.atan2(dy, dx);
    const phi = Math.acos(Math.min(1, Math.max(-1, circle.r / dist)));
    const candidates = [base + phi, base - phi];

    let best = candidates[0];
    let bestScore = -Infinity;
    for (const ang of candidates) {
        const tx = circle.cx + Math.cos(ang) * circle.r;
        const ty = circle.cy + Math.sin(ang) * circle.r;
        const vx = isEntering ? (tx - pt.x) : (pt.x - tx);
        const vy = isEntering ? (ty - pt.y) : (pt.y - ty);
        const dirX = ccw ? Math.sin(ang) : -Math.sin(ang);
        const dirY = ccw ? -Math.cos(ang) : Math.cos(ang);
        const score = vx * dirX + vy * dirY;
        if (score > bestScore) {
            bestScore = score;
            best = ang;
        }
    }

    return {
        x: circle.cx + Math.cos(best) * circle.r,
        y: circle.cy + Math.sin(best) * circle.r,
        angle: best
    };
}

function getOuterCommonTangent(c1, c2, ccw) {
    const dx = c2.cx - c1.cx;
    const dy = c2.cy - c1.cy;
    const dist = Math.hypot(dx, dy);
    if (dist < 1e-6) return null;
    const base = Math.atan2(dy, dx);
    const cosAlpha = Math.min(1, Math.max(-1, (c1.r - c2.r) / dist));
    const alpha = Math.acos(cosAlpha);

    const angles = [base + alpha, base - alpha];
    let best = null;
    let bestScore = -Infinity;
    for (const ang of angles) {
        const p1 = { x: c1.cx + Math.cos(ang) * c1.r, y: c1.cy + Math.sin(ang) * c1.r, angle: ang };
        const p2 = { x: c2.cx + Math.cos(ang) * c2.r, y: c2.cy + Math.sin(ang) * c2.r, angle: ang };
        const vx = p2.x - p1.x;
        const vy = p2.y - p1.y;
        const dirX = ccw ? Math.sin(ang) : -Math.sin(ang);
        const dirY = ccw ? -Math.cos(ang) : Math.cos(ang);
        const score = vx * dirX + vy * dirY;
        if (score > bestScore) {
            bestScore = score;
            best = { p1, p2 };
        }
    }
    return best;
}

function getSideOuterCotangent(sideId, toOuter, ccw) {
    const side = getTrackCircle(sideId);
    const step = (ccw ? -1 : 1) * (toOuter ? 1 : -1);
    const dTarget = ((sideId - 1 + step + 8) % 8) + 1;
    const theta = dZoneAngle(dTarget);
    const ux = Math.cos(theta);
    const uy = Math.sin(theta);

    // 內切包絡圓：同時內切於最外圓 (半徑 1) 與內切包覆側邊圓 (半徑 sr)
    const cx = side.cx;
    const cy = side.cy;
    const sr = side.r;
    const dot = ux * cx + uy * cy;
    const c2 = cx * cx + cy * cy;
    const num = 1 - 2 * dot + c2 - sr * sr;
    const den = 2 * (1 - dot - sr);
    const R = Math.max(0.15, num / Math.max(1e-6, den));

    const coCenter = { cx: (1 - R) * ux, cy: (1 - R) * uy, r: R };
    const touchOuter = { x: ux, y: uy, angle: theta };
    const touchSideAngle = Math.atan2(cy - coCenter.cy, cx - coCenter.cx);
    const touchSide = {
        x: cx + Math.cos(touchSideAngle) * sr,
        y: cy + Math.sin(touchSideAngle) * sr,
        angle: touchSideAngle
    };
    const coSideAngle = touchSideAngle;

    return {
        coCenter,
        startPoint: toOuter ? touchSide : touchOuter,
        endPoint: toOuter ? touchOuter : touchSide,
        startAngleOnCo: toOuter ? coSideAngle : theta,
        endAngleOnCo: toOuter ? theta : coSideAngle
    };
}

function pushArcIfNonZero(primitives, circle, startAngle, endAngle, ccw, laps) {
    const diff = ccw ? normAngle(startAngle - endAngle) : normAngle(endAngle - startAngle);
    if (diff > 1e-4 || laps > 0) {
        primitives.push({
            type: 'arc',
            cx: circle.cx,
            cy: circle.cy,
            r: circle.r,
            startAngle,
            endAngle,
            ccw,
            laps
        });
    }
}

function buildSlideGeometry(tokens) {
    const primitives = [];
    const nodes = [];
    const tracksUsed = new Set();

    for (const tok of tokens) {
        if (NODE_OPS.has(tok.op)) {
            nodes.push({ token: tok, pos: getNodePos(tok) });
        } else {
            tracksUsed.add(tok.param);
        }
    }

    let currentPos = getNodePos(tokens[0]);
    let idx = 0;

    while (idx < tokens.length - 1) {
        const cur = tokens[idx];
        const next = tokens[idx + 1];

        if (NODE_OPS.has(cur.op) && NODE_OPS.has(next.op)) {
            const pEnd = getNodePos(next);
            primitives.push({ type: 'line', from: currentPos, to: pEnd });
            currentPos = pEnd;
            idx += 1;
            continue;
        }

        if (NODE_OPS.has(cur.op) && TRACK_OPS.has(next.op)) {
            const ccw = next.op === 'P';
            let tIdx = idx + 1;
            const cStart = getTrackCircle(next.param);
            const entry = getPointCircleTangent(currentPos, cStart, ccw, true);
            if (Math.hypot(entry.x - currentPos.x, entry.y - currentPos.y) > 1e-4) {
                primitives.push({ type: 'line', from: currentPos, to: { x: entry.x, y: entry.y } });
            }

            let curTrackAngle = entry.angle;
            let curCircle = cStart;
            let extraLaps = 0;

            while (tIdx < tokens.length - 1 && TRACK_OPS.has(tokens[tIdx + 1].op)) {
                const tCur = tokens[tIdx];
                const tNext = tokens[tIdx + 1];
                if (tCur.param === tNext.param) {
                    extraLaps += 1;
                } else {
                    const nextCircle = getTrackCircle(tNext.param);
                    if (tCur.param === 9 || tNext.param === 9) {
                        const sideId = tCur.param === 9 ? tNext.param : tCur.param;
                        const toOuter = tNext.param === 9;
                        const co = getSideOuterCotangent(sideId, toOuter, ccw);
                        const arcEndAng = Math.atan2(co.startPoint.y - curCircle.cy, co.startPoint.x - curCircle.cx);
                        pushArcIfNonZero(primitives, curCircle, curTrackAngle, arcEndAng, ccw, extraLaps);
                        extraLaps = 0;
                        primitives.push({
                            type: 'arc',
                            cx: co.coCenter.cx,
                            cy: co.coCenter.cy,
                            r: co.coCenter.r,
                            startAngle: co.startAngleOnCo,
                            endAngle: co.endAngleOnCo,
                            ccw
                        });
                        curCircle = nextCircle;
                        curTrackAngle = Math.atan2(co.endPoint.y - curCircle.cy, co.endPoint.x - curCircle.cx);
                    } else {
                        const tan = getOuterCommonTangent(curCircle, nextCircle, ccw);
                        if (tan) {
                            pushArcIfNonZero(primitives, curCircle, curTrackAngle, tan.p1.angle, ccw, extraLaps);
                            extraLaps = 0;
                            primitives.push({ type: 'line', from: tan.p1, to: tan.p2 });
                            curCircle = nextCircle;
                            curTrackAngle = tan.p2.angle;
                        }
                    }
                }
                tIdx += 1;
            }

            const exitNode = tokens[tIdx + 1];
            const exitPos = getNodePos(exitNode);
            const exitTan = getPointCircleTangent(exitPos, curCircle, ccw, false);

            let diff = ccw ? normAngle(curTrackAngle - exitTan.angle) : normAngle(exitTan.angle - curTrackAngle);
            if (diff < 1e-4 && extraLaps === 0) {
                extraLaps = 1;
            }
            primitives.push({
                type: 'arc',
                cx: curCircle.cx,
                cy: curCircle.cy,
                r: curCircle.r,
                startAngle: curTrackAngle,
                endAngle: exitTan.angle,
                ccw,
                laps: extraLaps
            });

            if (Math.hypot(exitPos.x - exitTan.x, exitPos.y - exitTan.y) > 1e-4) {
                primitives.push({ type: 'line', from: { x: exitTan.x, y: exitTan.y }, to: exitPos });
            }

            currentPos = exitPos;
            idx = tIdx + 1;
            continue;
        }

        idx += 1;
    }

    return { primitives, nodes, tracksUsed };
}

/**
 * 仿照 chartGeometry.js PathRecorder 建構與標準座標系（scaleBase = 100）一致的弧長參數化路徑。
 */
class SlideCodePath {
    constructor(primitives, baseRadius) {
        this.segments = [];
        this.totalLength = 0;

        for (const p of primitives) {
            if (p.type === 'line') {
                const sx = p.from.x * baseRadius;
                const sy = p.from.y * baseRadius;
                const ex = p.to.x * baseRadius;
                const ey = p.to.y * baseRadius;
                const length = Math.hypot(ex - sx, ey - sy);
                if (length < 1e-5) continue;
                this.segments.push({
                    type: 'line',
                    start: { x: sx, y: sy },
                    end: { x: ex, y: ey },
                    rot: Math.atan2(ey - sy, ex - sx),
                    length,
                    cumLength: this.totalLength
                });
                this.totalLength += length;
            } else if (p.type === 'arc') {
                let diff = p.endAngle - p.startAngle;
                if (!p.ccw && diff <= 0) diff += Math.PI * 2;
                if (p.ccw && diff >= 0) diff -= Math.PI * 2;
                if (p.laps) diff += (p.ccw ? -1 : 1) * p.laps * Math.PI * 2;
                const r = p.r * baseRadius;
                const length = Math.abs(diff * r);
                if (length < 1e-5) continue;
                this.segments.push({
                    type: 'arc',
                    cx: p.cx * baseRadius,
                    cy: p.cy * baseRadius,
                    r,
                    startAngle: p.startAngle,
                    diff,
                    length,
                    cumLength: this.totalLength
                });
                this.totalLength += length;
            }
        }
    }

    getPointAt(t) {
        if (this.segments.length === 0) return { x: 0, y: 0, rot: 0 };
        const clamped = Math.max(0, Math.min(1, t));
        const targetLen = clamped * this.totalLength;

        let seg = this.segments[this.segments.length - 1];
        for (let i = 0; i < this.segments.length; i++) {
            const s = this.segments[i];
            if (targetLen <= s.cumLength + s.length) {
                seg = s;
                break;
            }
        }

        const localT = seg.length === 0 ? 1 : (targetLen - seg.cumLength) / seg.length;
        if (seg.type === 'line') {
            return {
                x: seg.start.x + (seg.end.x - seg.start.x) * localT,
                y: seg.start.y + (seg.end.y - seg.start.y) * localT,
                rot: seg.rot
            };
        }
        const curAng = seg.startAngle + seg.diff * localT;
        return {
            x: seg.cx + seg.r * Math.cos(curAng),
            y: seg.cy + seg.r * Math.sin(curAng),
            rot: curAng + (seg.diff > 0 ? Math.PI / 2 : -Math.PI / 2)
        };
    }

    buildArrowCache(spacing) {
        if (this.totalLength <= 2) return [];
        const count = Math.floor((this.totalLength - 2) / spacing);
        const arrows = [];
        for (let i = count; i > 0; i--) {
            const dist = i * spacing;
            const pt = this.getPointAt(dist / this.totalLength);
            arrows.push({ x: pt.x, y: pt.y, rad: pt.rot + Math.PI, dist });
        }
        return arrows;
    }
}

// --- 判定隊列推導 ---

function samplePrimitives(primitives, countPerSeg = 16) {
    const pts = [];
    for (const seg of primitives) {
        if (seg.type === 'line') {
            for (let s = 0; s <= countPerSeg; s++) {
                const t = s / countPerSeg;
                pts.push({
                    x: seg.from.x + (seg.to.x - seg.from.x) * t,
                    y: seg.from.y + (seg.to.y - seg.from.y) * t
                });
            }
        } else if (seg.type === 'arc') {
            let diff = seg.endAngle - seg.startAngle;
            if (!seg.ccw && diff <= 0) diff += Math.PI * 2;
            if (seg.ccw && diff >= 0) diff -= Math.PI * 2;
            if (seg.laps) diff += (seg.ccw ? -1 : 1) * seg.laps * Math.PI * 2;
            const steps = Math.max(8, Math.ceil(Math.abs(diff) / (Math.PI / 16)));
            for (let s = 0; s <= steps; s++) {
                const a = seg.startAngle + diff * (s / steps);
                pts.push({ x: seg.cx + Math.cos(a) * seg.r, y: seg.cy + Math.sin(a) * seg.r });
            }
        }
    }
    return pts;
}

function classifyPointZone(x, y) {
    const r = Math.hypot(x, y);
    if (r < 0.21) return 'C';
    const ang = normAngle(Math.atan2(y, x));
    const shifted = normAngle(ang + (2.5 * Math.PI / 4) + (Math.PI / 8));
    const idx = Math.floor(shifted / (Math.PI / 4)) % 8;
    return `${r >= 0.68 ? 'A' : 'B'}${idx + 1}`;
}

function estimateJudgmentQueue(tokens, primitives) {
    const samples = samplePrimitives(primitives, 20);
    if (samples.length === 0) {
        return tokens.filter((t) => NODE_OPS.has(t.op)).map((t) => (t.op === 'X' || t.op === 'K') ? `A${t.param}` : formatToken(t));
    }
    const queue = [];
    for (const pt of samples) {
        const zone = classifyPointZone(pt.x, pt.y);
        if (zone && queue[queue.length - 1] !== zone) queue.push(zone);
    }
    return queue;
}

// --- Simai 全譜面 Slide Code 時間軸掃描器 ---

function parseSlideDurationStr(str, currentBpm) {
    if (!str || typeof str !== 'string') return { time: -1, delay: -1 };
    const clean = str.trim();
    if (!clean) return { time: -1, delay: -1 };

    let delayOverride = null;
    let moveStr = clean;
    if (clean.includes('##')) {
        const parts = clean.split('##');
        if (parts.length !== 2) return { time: -1, delay: -1 };
        delayOverride = parseFloat(parts[0].trim());
        moveStr = parts[1].trim();
        if (!Number.isFinite(delayOverride) || delayOverride < 0 || !moveStr) return { time: -1, delay: -1 };
    }

    let bpm = currentBpm;
    let body = moveStr;
    if (body.includes('#')) {
        const parts = body.split('#');
        if (parts.length !== 2) return { time: -1, delay: -1 };
        const left = parts[0].trim();
        const right = parts[1].trim();
        if (left === '') {
            // [#seconds]
            const sec = parseFloat(right);
            if (!Number.isFinite(sec) || sec <= 0) return { time: -1, delay: -1 };
            return { time: sec, delay: delayOverride !== null ? delayOverride : 60 / currentBpm };
        }
        const customBpm = parseFloat(left);
        if (!Number.isFinite(customBpm) || customBpm <= 0) return { time: -1, delay: -1 };
        bpm = customBpm;
        body = right;
    }

    if (body.includes(':')) {
        const [divStr, countStr] = body.split(':');
        const div = parseFloat(divStr);
        const cnt = parseFloat(countStr);
        if (!Number.isFinite(div) || div <= 0 || !Number.isFinite(cnt) || cnt <= 0) {
            return { time: -1, delay: -1 };
        }
        const time = (60 / bpm) * (4 / div) * cnt;
        return { time, delay: delayOverride !== null ? delayOverride : 60 / bpm };
    }

    const sec = parseFloat(body);
    if (Number.isFinite(sec) && sec > 0) {
        return { time: sec, delay: delayOverride !== null ? delayOverride : 60 / bpm };
    }
    return { time: -1, delay: -1 };
}

/**
 * 掃描整份譜面文字，抽出所有合法的 Slide Code 音符及其時間軸屬性。
 */
function scanChartSlideCodes(chartText, firstOffset = 0) {
    if (!chartText || typeof chartText !== 'string') return [];

    // 去除 /* ... */ 多行註解、|| 單行註解與空白換行
    const noComments = chartText
        .replace(/\/\*[\s\S]*?\*\//g, '')
        .split(/\r?\n/)
        .map((line) => {
            const idx = line.indexOf('||');
            return idx >= 0 ? line.slice(0, idx) : line;
        })
        .join('')
        .replace(/\s+/g, '');

    if (!noComments) return [];

    const results = [];
    let nowTime = Number.isFinite(firstOffset) ? firstOffset : 0;
    let bpm = 120;
    let beatDiv = 4;
    let customStepSec = null;
    let hispeed = 1;

    // 依逗號切割（跳過 ()、{}、[] 內部的內容，避免誤切）
    const cells = [];
    let depthParen = 0;
    let depthBrace = 0;
    let depthBrack = 0;
    let start = 0;
    for (let i = 0; i < noComments.length; i++) {
        const ch = noComments[i];
        if (ch === '(') depthParen += 1;
        else if (ch === ')') depthParen = Math.max(0, depthParen - 1);
        else if (ch === '{') depthBrace += 1;
        else if (ch === '}') depthBrace = Math.max(0, depthBrace - 1);
        else if (ch === '[') depthBrack += 1;
        else if (ch === ']') depthBrack = Math.max(0, depthBrack - 1);
        else if (ch === ',' && depthParen === 0 && depthBrace === 0 && depthBrack === 0) {
            cells.push(noComments.slice(start, i));
            start = i + 1;
        }
    }
    if (start < noComments.length) {
        cells.push(noComments.slice(start));
    }

    const baseRadius = 100 * 0.889 * 0.5;
    const standardSlideRe = /(-|\^|<|>|v|pp|qq|p|q|s|z|w|V)/;
    const isSlideGroup = (g) => {
        if (!g || !g.includes('[')) return false;
        const noBr = g.replace(/\[[^\]]*\]/g, '');
        if (noBr.includes('h')) return false;
        return standardSlideRe.test(noBr) || /[ABCKPQ]/.test(noBr);
    };

    for (let cellIdx = 0; cellIdx < cells.length; cellIdx++) {
        let cell = cells[cellIdx];

        // 解析前置控制標籤：(BPM)、{beat}、HS*x
        while (cell.length > 0) {
            if (cell.startsWith('(')) {
                const end = cell.indexOf(')');
                if (end < 0) break;
                const val = parseFloat(cell.slice(1, end));
                if (Number.isFinite(val) && val > 0) bpm = val;
                cell = cell.slice(end + 1);
            } else if (cell.startsWith('{')) {
                const end = cell.indexOf('}');
                if (end < 0) break;
                const inner = cell.slice(1, end);
                if (inner.startsWith('#')) {
                    const sec = parseFloat(inner.slice(1));
                    customStepSec = Number.isFinite(sec) && sec > 0 ? sec : null;
                } else {
                    const val = parseFloat(inner);
                    if (Number.isFinite(val) && val > 0) {
                        beatDiv = val;
                        customStepSec = null;
                    }
                }
                cell = cell.slice(end + 1);
            } else if (cell.startsWith('<HS*') || cell.startsWith('HS*')) {
                const m = cell.match(/^<?HS\*([0-9.]+)>?/);
                if (!m) break;
                const val = parseFloat(m[1]);
                if (Number.isFinite(val) && val > 0) hispeed = val;
                cell = cell.slice(m[0].length);
            } else {
                break;
            }
        }

        // 尾端連寫 E 結尾安全剝離（例如 1P3K5[4:1]E）
        if (cellIdx === cells.length - 1 && cell.endsWith('E')) {
            cell = cell.slice(0, -1);
        }

        if (cell && cell !== 'E') {
            // 支援反引號 ` 偽多押
            const rawSubNotes = cell.includes('`') ? cell.split('`') : [cell];

            for (let subIdx = 0; subIdx < rawSubNotes.length; subIdx++) {
                const subCell = rawSubNotes[subIdx];
                if (!subCell) continue;
                const noteTime = cell.includes('`') ? nowTime + subIdx * 0.001 : nowTime;

                const groups = subCell.split('/').filter(Boolean);
                const isHeadDouble = groups.length > 1;
                let slideCountInSplit = 0;
                if (groups.length > 1) {
                    for (const g of groups) {
                        if (isSlideGroup(g)) {
                            slideCountInSplit += 1;
                            if (slideCountInSplit > 1) break;
                        }
                    }
                }
                const doubleSlide = slideCountInSplit > 1;

                for (const group of groups) {
                    // 處理同頭滑條（以 * 分隔）
                    const starParts = group.split('*');
                    const sameTimeSlide = starParts.length > 1;
                    const isSlideDouble = sameTimeSlide || doubleSlide;
                    let inheritedHead = null;

                    for (let sIdx = 0; sIdx < starParts.length; sIdx++) {
                        let part = starParts[sIdx];
                        if (!part) continue;

                        const isSameHead = sIdx > 0;
                        if (isSameHead && inheritedHead && !/^[1-8]/.test(part)) {
                            part = `${inheritedHead}${part}`;
                        }

                        // 偵測是否為 Slide Code 語法（包含 A/B/C/K/P/Q 且具有 [timing]）
                        const m = part.match(/^([1-8])([bxmhqf@?!$]*)([ABCKPQ0-9]+)([bxm]*)\[([^\]]+)\]$/);
                        if (!m) continue;

                        const startBtn = Number(m[1]);
                        inheritedHead = startBtn;
                        const headMods = m[2].toLowerCase();
                        const scBody = m[3];
                        const tailMods = m[4].toLowerCase();
                        const timingStr = m[5];

                        if (!/[ABCKPQ]/.test(scBody)) continue;

                        const parsed = parseAndValidateSlideCode(`${startBtn}${scBody}`);
                        if (!parsed.ok) continue;

                        const dur = parseSlideDurationStr(timingStr, bpm);
                        if (dur.time <= 0) continue;

                        const path = new SlideCodePath(parsed.geometry.primitives, baseRadius);
                        if (path.totalLength < 1e-4) continue;

                        const isHeadBreak = headMods.includes('b');
                        const isSlideBreak = tailMods.includes('b') || (headMods.includes('b') && !tailMods);

                        results.push({
                            time: noteTime,
                            startButton: startBtn,
                            slideDelay: dur.delay,
                            slideDuration: dur.time,
                            hispeed,
                            isHeadBreak,
                            isSlideBreak,
                            isEx: headMods.includes('x'),
                            isHeadDouble,
                            isSlideDouble,
                            isMultiple: sameTimeSlide,
                            noHead: headMods.includes('?'),
                            hideHead: isSameHead || headMods.includes('!'),
                            path,
                            arrowCache: null,
                            arrowCacheSpacing: -1
                        });
                    }
                }
            }
        }

        nowTime += customStepSec !== null ? customStepSec : (60 / bpm) * (4 / beatDiv);
    }

    return results;
}

// --- 外掛主進入點 ---

export default function activate(ctx) {
    const t = (key, params) => ctx.i18n ? ctx.i18n.t(key, params) : key;
    ctx.i18n?.registerTranslations(TRANSLATIONS);

    const skinImages = loadSkinImages();
    let settings = ctx.ui.getSettings(SETTINGS_SCHEMA);
    let currentInput = DEFAULT_SAMPLE;
    let parsedResult = parseAndValidateSlideCode(currentInput);
    let chartSlides = [];

    const refreshChartSlides = () => {
        const snap = ctx.chart?.getSnapshot?.();
        let text = ctx.editor?.getText?.() || '';
        if (!text && snap?.maidata?.inote && snap.difficulty !== undefined) {
            text = snap.maidata.inote[snap.difficulty] || '';
        }
        chartSlides = scanChartSlideCodes(text, 0);
        if (settings.panelVisible) renderPanel();
        ctx.render?.requestRedraw();
    };

    // --- 浮動面板 (Shadow DOM) ---
    const widget = ctx.ui.createFloatingWidget({ id: 'slidecode-panel', position: 'right' });
    const shadow = widget.element.attachShadow({ mode: 'open' });

    const styleEl = document.createElement('style');
    styleEl.textContent = `
        :host {
            display: block;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            color: #eef2f7;
            pointer-events: auto;
        }
        .card {
            width: 340px;
            max-height: 76vh;
            display: flex;
            flex-direction: column;
            gap: 9px;
            padding: 12px 14px;
            border-radius: 12px;
            background: rgba(20, 24, 34, 0.9);
            backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.14);
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
            font-size: 12px;
            line-height: 1.45;
            overflow: hidden;
        }
        .header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 8px;
        }
        .title {
            font-size: 13px;
            font-weight: 700;
            color: #93c5fd;
        }
        .sub-stat {
            font-size: 11px;
            color: #7dd3fc;
            background: rgba(56, 189, 248, 0.12);
            border: 1px solid rgba(56, 189, 248, 0.25);
            border-radius: 6px;
            padding: 3px 8px;
        }
        .badge {
            padding: 2px 8px;
            border-radius: 999px;
            font-size: 11px;
            font-weight: 600;
        }
        .badge.ok {
            background: rgba(34, 197, 94, 0.18);
            color: #86efac;
            border: 1px solid rgba(34, 197, 94, 0.4);
        }
        .badge.err {
            background: rgba(239, 68, 68, 0.2);
            color: #fca5a5;
            border: 1px solid rgba(239, 68, 68, 0.45);
        }
        .input-row {
            display: flex;
            gap: 6px;
        }
        input.code-input {
            flex: 1;
            min-width: 0;
            padding: 6px 9px;
            border-radius: 7px;
            border: 1px solid rgba(255, 255, 255, 0.18);
            background: rgba(10, 12, 18, 0.85);
            color: #f8fafc;
            font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
            font-size: 12px;
            outline: none;
        }
        input.code-input:focus {
            border-color: #60a5fa;
        }
        button {
            border: 1px solid rgba(255, 255, 255, 0.16);
            background: rgba(255, 255, 255, 0.08);
            color: #e2e8f0;
            border-radius: 7px;
            padding: 5px 8px;
            font-size: 11px;
            cursor: pointer;
            white-space: nowrap;
        }
        button:hover {
            background: rgba(96, 165, 250, 0.25);
            border-color: rgba(96, 165, 250, 0.5);
        }
        .presets {
            display: flex;
            flex-wrap: wrap;
            gap: 4px;
        }
        .preset-btn {
            padding: 3px 7px;
            font-size: 11px;
            border-radius: 6px;
        }
        .body {
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 8px;
            padding-right: 2px;
        }
        .section {
            background: rgba(255, 255, 255, 0.04);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 8px;
            padding: 7px 9px;
        }
        .section-title {
            font-size: 11px;
            font-weight: 600;
            color: #94a3b8;
            margin-bottom: 4px;
        }
        .mono {
            font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
            word-break: break-all;
            color: #fde68a;
        }
        .error-list {
            margin: 0;
            padding-left: 16px;
            color: #fca5a5;
        }
        .step-list {
            margin: 0;
            padding-left: 16px;
            display: flex;
            flex-direction: column;
            gap: 4px;
        }
        .step-bad {
            color: #fca5a5;
        }
        .step-code {
            font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
            color: #7dd3fc;
            margin-right: 4px;
        }
        .muted {
            color: #94a3b8;
        }
    `;

    const card = document.createElement('div');
    card.className = 'card';

    const header = document.createElement('div');
    header.className = 'header';
    const titleEl = document.createElement('span');
    titleEl.className = 'title';
    const badgeEl = document.createElement('span');
    badgeEl.className = 'badge';
    header.append(titleEl, badgeEl);

    const chartStatEl = document.createElement('div');
    chartStatEl.className = 'sub-stat';

    const inputRow = document.createElement('div');
    inputRow.className = 'input-row';
    const inputEl = document.createElement('input');
    inputEl.className = 'code-input';
    inputEl.type = 'text';
    inputEl.value = currentInput;

    const syncBtn = document.createElement('button');
    syncBtn.type = 'button';
    const clearBtn = document.createElement('button');
    clearBtn.type = 'button';
    inputRow.append(inputEl, syncBtn, clearBtn);

    const presetsEl = document.createElement('div');
    presetsEl.className = 'presets';
    for (const item of PRESET_EXAMPLES) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'preset-btn';
        btn.textContent = item.label;
        btn.title = item.code;
        btn.addEventListener('click', () => setSlideInput(item.code));
        presetsEl.appendChild(btn);
    }

    const bodyEl = document.createElement('div');
    bodyEl.className = 'body';

    card.append(header, chartStatEl, inputRow, presetsEl, bodyEl);
    shadow.append(styleEl, card);

    function applyVisibility() {
        widget.element.style.display = settings.panelVisible ? 'block' : 'none';
    }

    function renderPanel() {
        titleEl.textContent = t('title');
        chartStatEl.textContent = t('chartCountBadge', { count: chartSlides.length });
        inputEl.placeholder = t('placeholder');
        syncBtn.textContent = t('syncBtn');
        clearBtn.textContent = t('clearBtn');

        bodyEl.replaceChildren();

        if (parsedResult.empty) {
            badgeEl.textContent = '';
            badgeEl.style.display = 'none';
            const hint = document.createElement('div');
            hint.className = 'muted';
            hint.textContent = t('emptyHint');
            bodyEl.appendChild(hint);
            return;
        }

        badgeEl.style.display = 'inline-block';
        badgeEl.textContent = parsedResult.ok ? t('validStatus') : t('invalidStatus');
        badgeEl.className = `badge ${parsedResult.ok ? 'ok' : 'err'}`;

        if (parsedResult.tokens.length > 0) {
            const sec = document.createElement('div');
            sec.className = 'section';
            const st = document.createElement('div');
            st.className = 'section-title';
            st.textContent = t('expandedLabel');
            const val = document.createElement('div');
            val.className = 'mono';
            val.textContent = parsedResult.tokens.map(formatToken).join(' - ');
            sec.append(st, val);
            bodyEl.appendChild(sec);
        }

        if (parsedResult.errors.length > 0) {
            const sec = document.createElement('div');
            sec.className = 'section';
            const ul = document.createElement('ul');
            ul.className = 'error-list';
            for (const err of parsedResult.errors) {
                const li = document.createElement('li');
                li.textContent = err;
                ul.appendChild(li);
            }
            sec.appendChild(ul);
            bodyEl.appendChild(sec);
        }

        if (parsedResult.segments.length > 0) {
            const sec = document.createElement('div');
            sec.className = 'section';
            const st = document.createElement('div');
            st.className = 'section-title';
            st.textContent = t('stepsLabel');
            const ol = document.createElement('ol');
            ol.className = 'step-list';
            for (const seg of parsedResult.segments) {
                const li = document.createElement('li');
                if (!seg.valid) li.className = 'step-bad';
                const codeSpan = document.createElement('span');
                codeSpan.className = 'step-code';
                codeSpan.textContent = `${formatToken(seg.from)}→${formatToken(seg.to)}`;
                const descSpan = document.createElement('span');
                descSpan.textContent = seg.desc;
                li.append(codeSpan, descSpan);
                ol.appendChild(li);
            }
            sec.append(st, ol);
            bodyEl.appendChild(sec);
        }

        if (parsedResult.judgmentQueue.length > 0) {
            const sec = document.createElement('div');
            sec.className = 'section';
            const st = document.createElement('div');
            st.className = 'section-title';
            st.textContent = t('judgmentLabel');
            const val = document.createElement('div');
            val.className = 'mono';
            val.textContent = parsedResult.judgmentQueue.join(' → ');
            sec.append(st, val);
            bodyEl.appendChild(sec);
        }
    }

    function setSlideInput(val) {
        currentInput = val;
        if (inputEl.value !== val) inputEl.value = val;
        parsedResult = parseAndValidateSlideCode(val);
        renderPanel();
        ctx.render?.requestRedraw();
    }

    inputEl.addEventListener('input', () => setSlideInput(inputEl.value));

    syncBtn.addEventListener('click', () => {
        if (!ctx.editor) return;
        const text = ctx.editor.getText();
        const sel = ctx.editor.getSelection();
        const found = findSlideCodeNearCursor(text, sel.start, sel.end);
        if (found) setSlideInput(found);
        else ctx.ui.toast?.({ content: t('noEditorMatch'), type: 'info', timeout: 2500 });
    });

    clearBtn.addEventListener('click', () => setSlideInput(''));

    // --- 編輯器與系統事件監聽 ---
    const handleEditorSelection = (ev) => {
        if (!settings.followEditor || !ev) return;
        const found = findSlideCodeNearCursor(ev.text, ev.selectionStart, ev.selectionEnd);
        if (found && found !== currentInput) setSlideInput(found);
    };

    ctx.editor?.on('selectionchange', handleEditorSelection);
    ctx.editor?.on('input', (ev) => {
        refreshChartSlides();
        handleEditorSelection(ev);
    });
    ctx.events?.on('project:loaded', refreshChartSlides);
    ctx.events?.on('chart:decoded', refreshChartSlides);
    ctx.events?.on('maidata:changed', refreshChartSlides);

    // --- 主畫布相容渲染與靜態預覽 ---
    const timeFunction = (x) => (
        0.02160482279616 * x * x * x
        - 0.07553691072 * x * x
        + 0.43509924 * x
        + 0.000250029
    );

    const drawCenteredImg = (c, img, w, h) => {
        c.drawImage(img, -w * 0.5, -h * 0.5, w, h);
    };

    ctx.render?.registerOverlay({
        target: 'main',
        phase: 'afterNoteObjects',
        order: 20,
        includeInVideo: true,
        draw(rc) {
            const c = rc.ctx;
            const appSettings = ctx.settings?.getAll?.() || {};
            const noteBaseSize = Number(appSettings.noteBaseSize) || 11;
            const speed = Number(appSettings.speed) || 1;
            const speedFactor = speed * 0.8833 + 0.8167;
            const middleDistance = Number(appSettings.middleDistance ?? 0.25);
            const slideSpeed = Number(appSettings.slideSpeed ?? 0);
            const rotateStars = appSettings.rotateStars !== false;
            const pinkStars = Boolean(appSettings.pinkStars);
            const globalTime = Number.isFinite(rc.globalTime)
                ? rc.globalTime
                : (ctx.playback?.getState?.().globalTime ?? 0);

            // 1. 譜面時間軸同步渲染
            if (settings.chartPlaybackEnabled && chartSlides.length > 0) {
                const arrowSpacing = 0.3963 * noteBaseSize;
                const arrowSizeMul = noteBaseSize * 0.0909;
                const baseRadius = (rc.scaleBase || 100) * 0.889 * 0.5;

                for (let sIdx = 0; sIdx < chartSlides.length; sIdx++) {
                    const s = chartSlides[sIdx];
                    const noteT = s.time - globalTime;

                    let displayProgress = 0;
                    if (-noteT > s.slideDelay) {
                        displayProgress = (-noteT - s.slideDelay) / s.slideDuration;
                    }

                    if (displayProgress >= 1) continue;
                    const speedMult = speedFactor * (s.hispeed || 1);
                    const t = 1 - timeFunction(noteT * speedMult);
                    if (t <= -0.9 && noteT > 0) continue;

                    const displayT = Math.max(middleDistance, t);
                    const currentScale = t < middleDistance
                        ? Math.max(0, (t + 0.9) / (0.9 + middleDistance))
                        : 1;

                    const slideKey = s.isSlideBreak ? 'slide_break' : (s.isSlideDouble ? 'slide_each' : 'slide');
                    const slideImg = skinImages[slideKey] || skinImages.slide;
                    const slideStarKey = s.isSlideBreak ? 'star_break' : (s.isSlideDouble ? 'star_each' : 'star');
                    const slideStarImg = skinImages[slideStarKey] || skinImages.star;

                    // 1a. 繪製軌跡箭頭
                    if (isImgReady(slideImg)) {
                        if (!s.arrowCache || Math.abs(s.arrowCacheSpacing - arrowSpacing) > 1e-4) {
                            s.arrowCache = s.path.buildArrowCache(arrowSpacing);
                            s.arrowCacheSpacing = arrowSpacing;
                        }
                        const starDist = Math.max(0, displayProgress) * s.path.totalLength;
                        const isTapped = -noteT > 0;
                        const trackAlpha = isTapped
                            ? 1
                            : 0.75 * Math.min(1, Math.max(0, ((t - middleDistance) / Math.max(0.01, 1 - middleDistance)) + slideSpeed));

                        if (trackAlpha > 0.01) {
                            c.save();
                            c.globalAlpha = trackAlpha;
                            const dw = 6.3 * arrowSizeMul;
                            const dh = 8.46 * arrowSizeMul;
                            for (let aIdx = 0; aIdx < s.arrowCache.length; aIdx++) {
                                const arr = s.arrowCache[aIdx];
                                if (displayProgress > 0 && arr.dist <= starDist) continue;
                                c.save();
                                c.translate(arr.x, arr.y);
                                c.rotate(arr.rad);
                                drawCenteredImg(c, slideImg, dw, dh);
                                c.restore();
                            }
                            c.restore();
                        }
                    }

                    // 1b. 繪製導引弧與進場星星頭 (noteT > 0)
                    if (settings.renderApproachHead && !s.noHead && !s.hideHead && noteT > 0 && currentScale > 0.01) {
                        const ang = buttonAngle(s.startButton);
                        const headRotBase = ang + Math.PI / 2;
                        const arcKey = s.isHeadBreak ? 'arc_break' : (s.isHeadDouble ? 'arc_each' : 'arc_star');
                        const arcImg = skinImages[arcKey];
                        if (isImgReady(arcImg)) {
                            const arcSize = displayT * baseRadius * 2.25;
                            c.save();
                            if (currentScale !== 1) c.globalAlpha = currentScale;
                            c.rotate(headRotBase);
                            drawCenteredImg(c, arcImg, arcSize, arcSize);
                            c.restore();
                        }

                        const headStarKey = s.isMultiple
                            ? (s.isHeadBreak ? 'star_break_double' : (s.isHeadDouble ? 'star_each_double' : (pinkStars ? 'star_pink_double' : 'star_double')))
                            : (s.isHeadBreak ? 'star_break' : (s.isHeadDouble ? 'star_each' : (pinkStars ? 'star_pink' : 'star')));
                        const headStarImg = skinImages[headStarKey] || skinImages.star;

                        if (isImgReady(headStarImg)) {
                            const headPos = { x: Math.cos(ang) * baseRadius, y: Math.sin(ang) * baseRadius };
                            const headStarSize = noteBaseSize * currentScale;
                            c.save();
                            c.translate(headPos.x * displayT, headPos.y * displayT);
                            let headRot = headRotBase;
                            if (rotateStars) {
                                const rotSpeed = s.slideDuration > 0 ? Math.min(6, Math.max(0.5, 1.5 / s.slideDuration)) : 0;
                                headRot += globalTime * 2 * Math.PI * rotSpeed;
                            }
                            c.rotate(headRot);
                            drawCenteredImg(c, headStarImg, headStarSize, headStarSize);
                            c.restore();
                        }
                    }

                    // 1c. 繪製滑行星星 (noteT <= 0)
                    if (noteT <= 0 && isImgReady(slideStarImg)) {
                        const sz = s.slideDelay < 1e-4 ? 1 : Math.min(1, 1 - (noteT + s.slideDelay) / s.slideDelay);
                        if ((!s.hideHead || sz >= 1) && sz > 0.01) {
                            const pt = s.path.getPointAt(Math.max(0, Math.min(1, displayProgress)));
                            const starSize = noteBaseSize * sz * 1.45;
                            c.save();
                            c.globalAlpha = sz;
                            c.translate(pt.x, pt.y);
                            c.rotate(pt.rot + Math.PI * 0.5);
                            drawCenteredImg(c, slideStarImg, starSize, starSize);
                            c.restore();
                        }
                    }
                }
            }

            // 2. 面板條目靜態預覽（非影片匯出時可選顯示）
            if (!rc.isRenderingVideo && settings.inspectorPreview && parsedResult.ok) {
                const { primitives, nodes, tracksUsed } = parsedResult.geometry;
                if (!primitives || primitives.length === 0) return;
                const R = (rc.scaleBase || 100) * 0.889 * 0.5;

                if (settings.showTrackCircles && tracksUsed.size > 0) {
                    c.save();
                    c.setLineDash([1.6, 1.6]);
                    c.lineWidth = 0.55;
                    c.strokeStyle = 'rgba(125, 211, 252, 0.35)';
                    for (const id of tracksUsed) {
                        const tc = getTrackCircle(id);
                        c.beginPath();
                        c.arc(tc.cx * R, tc.cy * R, tc.r * R, 0, Math.PI * 2);
                        c.stroke();
                    }
                    c.restore();
                }

                c.save();
                c.lineCap = 'round';
                c.lineJoin = 'round';
                c.strokeStyle = 'rgba(56, 189, 248, 0.85)';
                c.lineWidth = 1.6;
                for (const seg of primitives) {
                    c.beginPath();
                    if (seg.type === 'line') {
                        c.moveTo(seg.from.x * R, seg.from.y * R);
                        c.lineTo(seg.to.x * R, seg.to.y * R);
                    } else if (seg.type === 'arc') {
                        c.arc(seg.cx * R, seg.cy * R, seg.r * R, seg.startAngle, seg.endAngle, seg.ccw);
                    }
                    c.stroke();
                }

                if (settings.showNodeLabels) {
                    c.font = 'bold 3px sans-serif';
                    c.textAlign = 'center';
                    c.textBaseline = 'middle';
                    for (let nIdx = 0; nIdx < nodes.length; nIdx++) {
                        const node = nodes[nIdx];
                        const px = node.pos.x * R;
                        const py = node.pos.y * R;
                        c.beginPath();
                        c.arc(px, py, nIdx === 0 || node.token.op === 'K' ? 2.2 : 1.5, 0, Math.PI * 2);
                        c.fillStyle = nIdx === 0 ? '#4ade80' : (node.token.op === 'K' ? '#fb7185' : '#f8fafc');
                        c.fill();
                        c.fillStyle = '#f8fafc';
                        c.fillText(formatToken(node.token), px, py - 3.6);
                    }
                }
                c.restore();
            }
        }
    });

    // --- 指令、選單與設定彈窗 ---
    const togglePanel = () => {
        settings = { ...settings, panelVisible: !settings.panelVisible };
        applyVisibility();
        if (settings.panelVisible) renderPanel();
    };

    const openSettings = ({ anchorEl } = {}) => {
        ctx.ui.openPopover({
            title: t('menuSettings'),
            schema: SETTINGS_SCHEMA,
            anchorEl,
            onChange: (key, value, allValues) => {
                settings = { ...allValues, [key]: value };
                applyVisibility();
                ctx.render?.requestRedraw();
            }
        });
    };

    ctx.commands?.register('togglePanel', togglePanel, { title: t('menuToggle') });
    ctx.commands?.register('openSettings', openSettings, { title: t('menuSettings') });

    ctx.ui.registerMenuItem({
        id: 'toggle-slidecode-panel',
        label: t('menuToggle'),
        labelKey: 'ext.com.wmcx.slidecode-explainer.menuToggle',
        onClick: togglePanel
    });

    ctx.ui.registerMenuItem({
        id: 'slidecode-settings',
        label: t('menuSettings'),
        labelKey: 'ext.com.wmcx.slidecode-explainer.menuSettings',
        onClick: openSettings
    });

    applyVisibility();
    refreshChartSlides();

    return () => {};
}
